<?php
namespace App\Services;
use App\Exceptions\ApiException;
use App\Models\{Business,User,Sale,SalePayment,SaleDebt,DebtAllocation,CustomerPayment,SaleReturn,Customer,IncentiveConfiguration,IncentiveAccount,IncentiveEntry,CommissionPayout,LoyaltyRedemption,LoyaltyRestoration,SaleItem,SaleReturnItem};
use App\Support\{Money,ExactMath,IncentiveMath,Quantity};
use App\Tenancy\TenantContext;
use Illuminate\Support\Facades\DB;
use Illuminate\Auth\Access\AuthorizationException;
class IncentiveService {
 public function __construct(private TenantContext $context,private FinancialActorService $actors){}
 private function owner(User $original):User{$actor=$this->actors->lock($original,'view_reports');if(!$actor->hasRole('owner'))throw new AuthorizationException;Business::whereKey($this->context->requireId())->lockForUpdate()->firstOrFail();return $actor;}
 public function configuration():?IncentiveConfiguration{$query=IncentiveConfiguration::orderByDesc('id');if(DB::transactionLevel()>0)$query->lockForUpdate();return $query->first();}
 public function previewConfiguration(User $actor,array $input):array{return DB::transaction(function()use($actor,$input){$this->owner($actor);$snapshot=$this->configurationSnapshot($input);return ['snapshot'=>$snapshot,'review_hash'=>SupervisorApprovalService::snapshotHash($snapshot)];});}
 public function configure(User $original,array $input):array{return DB::transaction(function()use($original,$input){$actor=$this->owner($original);$key=strtolower($input['operation_id']);$fingerprint=SupervisorApprovalService::snapshotHash($input);$existing=IncentiveConfiguration::where('operation_id',$key)->lockForUpdate()->first();if($existing){$this->replay($actor,$existing,$fingerprint);return ['configuration'=>$existing,'replayed'=>true];}$snapshot=$this->configurationSnapshot($input);if(!hash_equals(SupervisorApprovalService::snapshotHash($snapshot),$input['review_hash']??''))throw new ApiException('INCENTIVE_REVIEW_CHANGED','Review the incentive configuration again.',409);$record=IncentiveConfiguration::create([...$snapshot,'user_id'=>$actor->id,'device_id'=>$actor->currentAccessToken()->device_id,'request_fingerprint'=>$fingerprint]);activity('incentives')->performedOn($record)->causedBy($actor)->event('incentive_rates_configured')->withProperties(['attributes'=>['configuration_id'=>$record->publicId(),'loyalty_enabled'=>$record->loyalty_tsh_per_point!==null,'commission_enabled'=>$record->commission_basis_points!==null]])->log('Owner configured incentive rates');return ['configuration'=>$record,'replayed'=>false];},3);}
 private function configurationSnapshot(array $input):array{$flags=app(PlanFeatureService::class)->features();if((!$flags['loyalty']&&(($input['loyalty_tsh_per_point']??null)!==null||($input['loyalty_point_value']??null)!==null))||(!$flags['commissions']&&($input['commission_basis_points']??null)!==null))throw new ApiException('FEATURE_DISABLED','The selected incentive capability is disabled for this shop.',403);return ['operation_id'=>strtolower($input['operation_id']),'loyalty_tsh_per_point'=>$input['loyalty_tsh_per_point']??null,'loyalty_point_value'=>$input['loyalty_point_value']??null,'commission_basis_points'=>$input['commission_basis_points']??null,'reason'=>trim($input['reason'])];}
 private function replay(User $actor,$record,string $fingerprint):void{if($record->user_id!==$actor->id||$record->device_id!==$actor->currentAccessToken()->device_id||!hash_equals($record->request_fingerprint,$fingerprint))throw new ApiException('OPERATION_ID_REUSED','This reference belongs to different details or staff.',409);}
 /** All hooks run inside the originating sale/collection/return transaction with the shop locked. */
 public function recordSale(User $actor,Sale $sale):void{
  $this->requireTransaction();$actor->assertCurrentBusiness();$sale->assertCurrentBusiness();if($sale->cashier_id!==$actor->id)throw new \LogicException('Only the sale actor can establish incentive terms.');$account=IncentiveAccount::where('sale_id',$sale->id)->lockForUpdate()->first();if(!$account){$flags=app(PlanFeatureService::class)->features();$config=IncentiveConfiguration::where('created_at','<=',$sale->occurred_at??$sale->created_at)->orderByDesc('id')->lockForUpdate()->first();$account=IncentiveAccount::create(['sale_id'=>$sale->id,'cashier_id'=>$sale->cashier_id,'customer_id'=>$sale->customer_id,'configuration_id'=>$config?->id,'loyalty_tsh_per_point'=>$sale->customer_id&&$flags['loyalty']?$config?->loyalty_tsh_per_point:null,'commission_basis_points'=>$flags['commissions']?$config?->commission_basis_points:null]);}$this->consumeRedemption($actor,$sale);$this->sync($account,$sale,'sale',$sale->publicId());
 }
 public function recordCollection(CustomerPayment $payment):void{$this->requireTransaction();$payment->assertCurrentBusiness();$allocations=DebtAllocation::where('customer_payment_id',$payment->id)->orderBy('sale_debt_id')->get();foreach($allocations as$allocation){$debt=SaleDebt::findOrFail($allocation->sale_debt_id);$sale=Sale::whereKey($debt->sale_id)->lockForUpdate()->firstOrFail();$account=IncentiveAccount::where('sale_id',$sale->id)->lockForUpdate()->first();if($account)$this->sync($account,$sale,'collection',$payment->publicId());}}
 public function recordReturn(SaleReturn $return):void{$this->requireTransaction();$return->assertCurrentBusiness();$sale=Sale::whereKey($return->sale_id)->lockForUpdate()->firstOrFail();$account=IncentiveAccount::where('sale_id',$sale->id)->lockForUpdate()->first();if($account)$this->sync($account,$sale,'return',$return->publicId());$this->restoreRedemption($sale,$return);}
 private function requireTransaction():void{if(DB::transactionLevel()<1)throw new \LogicException('Incentive journals must commit with their domain transaction.');}
 private function checkedSum($query,string $column):int {
  if(DB::transactionLevel()>0){$value=0;foreach($query->orderBy('id')->lockForUpdate()->get([$column])as$row){try{$value=ExactMath::add($value,Quantity::parse((string)$row->{$column},allowNegative:true));}catch(\InvalidArgumentException|\OverflowException $e){throw new ApiException('VALIDATION_ERROR',$e->getMessage(),422);}}}else $value=(string)$query->sum($column);
  $value=(string)$value;$negative=str_starts_with($value,'-');$digits=ltrim($value,'-');$limit=$column==='qty_atoms'?PHP_INT_MAX:Money::MAX_AMOUNT;if(strlen($digits)>strlen((string)$limit)||(strlen($digits)===strlen((string)$limit)&&strcmp($digits,(string)$limit)>0))throw new ApiException('VALIDATION_ERROR','This incentive total exceeds exact reporting limits.',422);return $negative?-(int)$digits:(int)$digits;
 }
 private function sync(IncentiveAccount $account,Sale $sale,string $type,string $source):void{
  $key=$type.':'.$source;if(IncentiveEntry::where('incentive_account_id',$account->id)->where('event_key',$key)->lockForUpdate()->first())return;
  $paid=$this->checkedSum(SalePayment::where('sale_id',$sale->id)->whereIn('method',['cash','mpesa']),'amount');$debt=SaleDebt::where('sale_id',$sale->id)->first();if($debt)$paid=Money::amount(ExactMath::add($paid,$this->checkedSum(DebtAllocation::where('sale_debt_id',$debt->id),'amount')));
  $cashReturned=$this->checkedSum(SaleReturn::where('sale_id',$sale->id),'cash_refund');$mobileReturned=$this->checkedSum(SaleReturn::where('sale_id',$sale->id),'mobile_refund');$paid=max(0,$paid-ExactMath::add($cashReturned,$mobileReturned));$paid=min($sale->total,$paid);
  $earned=IncentiveMath::earned($sale->total,$sale->vat_amount,$paid,$account->loyalty_tsh_per_point,$account->commission_basis_points);$previous=IncentiveEntry::where('incentive_account_id',$account->id)->orderByDesc('id')->lockForUpdate()->first();
  IncentiveEntry::create(['incentive_account_id'=>$account->id,'cashier_id'=>$account->cashier_id,'customer_id'=>$account->customer_id,'event_key'=>$key,'event_type'=>$type,...$earned,'points_delta'=>$earned['points_total']-($previous?->points_total??0),'commission_delta'=>$earned['commission_total']-($previous?->commission_total??0)]);
 }
 public function loyalty(Customer $customer):array{$customer->assertCurrentBusiness();$earned=$this->checkedSum(IncentiveEntry::where('customer_id',$customer->id),'points_delta');$spent=$this->checkedSum(LoyaltyRedemption::where('customer_id',$customer->id),'points');$restored=$this->checkedSum(LoyaltyRestoration::where('customer_id',$customer->id),'points');$points=ExactMath::add($earned,$restored)-$spent;return ['customer_id'=>$customer->publicId(),'points'=>$points,'available_points'=>max(0,$points),'refund_carry'=>max(0,-$points),'point_value'=>$this->configuration()?->loyalty_point_value,'redemption_enabled'=>$this->configuration()?->loyalty_point_value!==null,'configuration_enabled'=>$this->configuration()?->loyalty_tsh_per_point!==null];}
 public function previewRedemption(User $actor,array $input,int $remainingValue):array {
  $this->requireTransaction();$actor->assertCurrentBusiness();if(!$actor->can('sell'))throw new AuthorizationException;$points=Money::amount($input['loyalty_points']??0);if(!$points)return [];if(!app(PlanFeatureService::class)->features()['loyalty'])throw new ApiException('FEATURE_DISABLED','Loyalty redemption is disabled for this shop.',403);
  if(!isset($input['customer_id']))throw new ApiException('VALIDATION_ERROR','Select the loyalty customer before redeeming points.',422,'customer_id');$customer=(new Customer)->resolveRouteBindingQuery(Customer::query(),$input['customer_id'])->lockForUpdate()->firstOrFail();$config=$this->configuration();if(!$config?->loyalty_point_value)throw new ApiException('LOYALTY_REDEMPTION_DISABLED','The owner has not configured a redemption value.',409);$balance=$this->loyalty($customer);$max=min($balance['available_points'],intdiv(Money::amount($remainingValue),$config->loyalty_point_value));if($points>$max)throw new ApiException('INSUFFICIENT_LOYALTY_POINTS','Redeem whole points within the positive balance and remaining cart value.',422,'loyalty_points',['maximum_points'=>$max]);
  return ['customer_id'=>$customer->publicId(),'configuration_id'=>$config->publicId(),'points'=>$points,'point_value'=>$config->loyalty_point_value,'discount_amount'=>Money::amount(ExactMath::multiply($points,$config->loyalty_point_value)),'balance_before'=>$balance['points'],'maximum_points'=>$max];
 }
 private function consumeRedemption(User $actor,Sale $sale):void {
  $snapshot=$sale->loyalty_redemption;if(!is_array($snapshot)||!($snapshot['points']??0))return;if(LoyaltyRedemption::where('sale_id',$sale->id)->lockForUpdate()->first())return;$fresh=$this->previewRedemption($actor,['customer_id'=>$snapshot['customer_id'],'loyalty_points'=>$snapshot['points']],Money::amount(ExactMath::add($sale->total,$snapshot['discount_amount'])));foreach(['customer_id','configuration_id','points','point_value','discount_amount','balance_before']as$key)if(($snapshot[$key]??null)!==($fresh[$key]??null))throw new ApiException('SALE_CHANGED','The loyalty balance or value changed. Review this sale again.',409);$customer=(new Customer)->resolveRouteBinding($snapshot['customer_id']);$config=(new IncentiveConfiguration)->resolveRouteBinding($snapshot['configuration_id']);if($sale->customer_id!==$customer->id)throw new ApiException('SALE_CHANGED','The loyalty customer changed.',409);LoyaltyRedemption::create(['sale_id'=>$sale->id,'customer_id'=>$customer->id,'configuration_id'=>$config->id,'points'=>$fresh['points'],'point_value'=>$fresh['point_value'],'discount_amount'=>$fresh['discount_amount']]);
 }
 private function restoreRedemption(Sale $sale,SaleReturn $return):void {
  $redemption=LoyaltyRedemption::where('sale_id',$sale->id)->lockForUpdate()->first();if(!$redemption||LoyaltyRestoration::where('sale_return_id',$return->id)->lockForUpdate()->first())return;$entitlement=0;
  foreach($sale->lines as$i=>$line){$discount=Money::amount($line['loyalty_discount']??0);if(!$discount)continue;$atoms=Quantity::parse($line['base_qty'],$line['quantity_type']==='weight');$returned=$this->checkedSum(SaleReturnItem::where('sale_id',$sale->id)->whereIn('sale_item_id',SaleItem::select('id')->where('sale_id',$sale->id)->where('line_index',$i)),'qty_atoms');if($returned>$atoms)throw new \LogicException('Returned loyalty quantities exceed their original sale.');$entitlement=ExactMath::add($entitlement,ExactMath::roundProportion($discount,$returned,$atoms));}
  if($entitlement>$redemption->discount_amount)throw new \LogicException('Returned loyalty discounts exceed the redemption.');$target=ExactMath::roundProportion($redemption->points,$entitlement,$redemption->discount_amount);$previous=$this->checkedSum(LoyaltyRestoration::where('loyalty_redemption_id',$redemption->id),'points');$restore=max(0,$target-$previous);LoyaltyRestoration::create(['loyalty_redemption_id'=>$redemption->id,'sale_return_id'=>$return->id,'customer_id'=>$redemption->customer_id,'points'=>$restore]);
 }
 public function commission(User $cashier):array{$cashier->assertCurrentBusiness();$earned=$this->checkedSum(IncentiveEntry::where('cashier_id',$cashier->id),'commission_delta');$paid=$this->checkedSum(CommissionPayout::where('cashier_id',$cashier->id),'amount');$balance=$earned-$paid;return ['cashier_id'=>$cashier->publicId(),'cashier_name'=>$cashier->name,'earned'=>$earned,'paid'=>$paid,'balance'=>$balance,'payable'=>max(0,$balance),'refund_carry'=>max(0,-$balance)];}
 public function previewPayout(User $actor,array $input):array{return DB::transaction(function()use($actor,$input){$this->owner($actor);$snapshot=$this->payoutSnapshot($input);return ['snapshot'=>$snapshot,'review_hash'=>SupervisorApprovalService::snapshotHash($snapshot)];});}
 public function payout(User $original,array $input):array{return DB::transaction(function()use($original,$input){$actor=$this->owner($original);$key=strtolower($input['operation_id']);$fingerprint=SupervisorApprovalService::snapshotHash($input);$existing=CommissionPayout::where('operation_id',$key)->lockForUpdate()->first();if($existing){$this->replay($actor,$existing,$fingerprint);return ['payout'=>$existing,'replayed'=>true,'external_transfer_executed'=>false];}$snapshot=$this->payoutSnapshot($input);if(!hash_equals(SupervisorApprovalService::snapshotHash($snapshot),$input['review_hash']??''))throw new ApiException('INCENTIVE_REVIEW_CHANGED','The commission balance changed. Review the payout again.',409);$hash=hash('sha256',$snapshot['external_reference']);if(CommissionPayout::where('external_reference_hash',$hash)->exists())throw new ApiException('PAYMENT_REFERENCE_REUSED','This payout reference has already been recorded.',409);$cashier=(new User)->resolveRouteBindingQuery(User::query(),$input['cashier_id'])->firstOrFail();$payout=CommissionPayout::create(['cashier_id'=>$cashier->id,'user_id'=>$actor->id,'device_id'=>$actor->currentAccessToken()->device_id,'operation_id'=>$key,'request_fingerprint'=>$fingerprint,'amount'=>$snapshot['amount'],'paid_on'=>$snapshot['paid_on'],'external_reference'=>$snapshot['external_reference'],'external_reference_hash'=>$hash,'reason'=>$snapshot['reason']]);activity('incentives')->performedOn($payout)->causedBy($actor)->event('commission_payout_recorded')->withProperties(['attributes'=>['payout_id'=>$payout->publicId(),'amount'=>$payout->amount]])->log('External commission payout recorded');return ['payout'=>$payout,'replayed'=>false,'external_transfer_executed'=>false];},3);}
 private function payoutSnapshot(array $input):array{$cashier=(new User)->resolveRouteBindingQuery(User::query(),$input['cashier_id'])->firstOrFail();$amount=Money::amount($input['amount']);$balance=$this->commission($cashier);if($amount<1||$amount>$balance['payable'])throw new ApiException('INSUFFICIENT_COMMISSION','The payout exceeds the positive earned commission balance.',422,'amount');if(($input['external_payment_completed']??false)!==true)throw new ApiException('EXTERNAL_PAYMENT_REQUIRED','Record this only after completing the payment externally.',422);if($input['paid_on']>now('Africa/Dar_es_Salaam')->toDateString())throw new ApiException('VALIDATION_ERROR','The payout date cannot be in the future.',422,'paid_on');return ['operation_id'=>strtolower($input['operation_id']),'cashier_id'=>$cashier->publicId(),'amount'=>$amount,'payable_before'=>$balance['payable'],'paid_on'=>$input['paid_on'],'external_reference'=>trim($input['external_reference']),'reason'=>trim($input['reason']),'external_payment_completed'=>true];}
}
